import json,sys,collections
page=sys.argv[1]; patch=json.load(open(sys.argv[2]))
path=f'/home/sfmqrb/git/rishe/data/verification/page-{page}.json'
d=json.load(open(path),object_pairs_hook=collections.OrderedDict)
def ins(od,after,key,val):
    new=collections.OrderedDict()
    placed=False
    for k,v in od.items():
        new[k]=v
        if k==after:
            new[key]=val; placed=True
    if not placed: new[key]=val
    od.clear(); od.update(new)
miss=[]
for en in d['entries']:
    ei=str(en['entry'])
    if ei not in patch['entry']: miss.append('entry '+ei)
    else: ins(en,'note','note_fa',patch['entry'][ei])
    np=patch['nodes'].get(ei,{})
    for n in en['nodes']:
        nid=str(n['id'])
        if nid not in np: miss.append(f'entry {ei} node {nid}')
        else: ins(n,'derivation','derivation_fa',np[nid])
if miss:
    print('MISSING:',miss); sys.exit(1)
json.dump(d,open(path,'w'),ensure_ascii=False,indent=2)
open(path,'a').write('\n')
print('ok',page)
